import math


PI = 3.141592653589793


def select_constituents(constituents, record_length, rayleigh):
    selected = []
    status = {}
    minimum = 360 * rayleigh
    for constituent in constituents:
        name = constituent["name"]
        speed = constituent["speed"]
        if speed * record_length < minimum:
            status[name] = "short"
            continue
        conflict = next((chosen for chosen in selected
                         if abs(speed - chosen["speed"]) * record_length < minimum),
                        None)
        if conflict is not None:
            status[name] = "conflict:" + conflict["name"]
            continue
        status[name] = "fitted"
        selected.append(constituent)
    return selected, status


def angle(speed, time):
    degrees = speed * time
    reduced = degrees - 360 * math.floor(degrees / 360)
    return reduced * PI / 180


def regressors(time, selected):
    features = [1.0]
    for constituent in selected:
        theta = angle(constituent["speed"], time)
        features.append(math.cos(theta))
        features.append(math.sin(theta))
    return features


def solve_with_inverse(matrix, right):
    dimension = len(matrix)
    aug = [
        list(matrix[i]) + [right[i]] +
        [1.0 if i == j else 0.0 for j in range(dimension)]
        for i in range(dimension)
    ]
    for column in range(dimension):
        pivot = max(range(column, dimension),
                    key=lambda i: (abs(aug[i][column]), -i))
        if pivot != column:
            aug[column], aug[pivot] = aug[pivot], aug[column]
        for row in range(column + 1, dimension):
            factor = aug[row][column] / aug[column][column]
            for c in range(column, 2 * dimension + 1):
                aug[row][c] = aug[row][c] - factor * aug[column][c]
    solutions = []
    for column in range(dimension, 2 * dimension + 1):
        solution = [0.0] * dimension
        for i in range(dimension - 1, -1, -1):
            current = aug[i][column]
            for j in range(i + 1, dimension):
                current = current - aug[i][j] * solution[j]
            solution[i] = current / aug[i][i]
        solutions.append(solution)
    inverse = [
        [solutions[column + 1][row] for column in range(dimension)]
        for row in range(dimension)
    ]
    return solutions[0], inverse


def fit(values, times, selected):
    dimension = len(selected) * 2 + 1
    matrix = [[0.0] * dimension for _ in range(dimension)]
    right = [0.0] * dimension
    for time in sorted(times):
        vector = regressors(time, selected)
        observed = values[time]
        for i in range(dimension):
            right[i] += vector[i] * observed
            for j in range(dimension):
                matrix[i][j] += vector[i] * vector[j]
    coefficients, inverse = solve_with_inverse(matrix, right)
    constants = {}
    for i, constituent in enumerate(selected):
        a = coefficients[2 * i + 1]
        b = coefficients[2 * i + 2]
        amplitude = math.sqrt(a * a + b * b)
        phase = math.atan2(b, a) * 180 / PI
        if phase < 0:
            phase += 360
        constants[constituent["name"]] = {
            "speed": constituent["speed"],
            "a": a, "b": b, "amplitude": amplitude, "phase": phase,
            "index_a": 2 * i + 1, "index_b": 2 * i + 2,
        }
    return {
        "selected": selected, "coefficients": coefficients,
        "inverse": inverse, "mean_level": coefficients[0],
        "constants": constants, "unknowns": dimension,
    }

import math

from harmonic_fit import angle
from records import date_at_minute


def predict_height(model, time):
    result = model["mean_level"]
    for constituent in model["selected"]:
        constant = model["constants"][constituent["name"]]
        theta = angle(constituent["speed"], time)
        result += constant["a"] * math.cos(theta) + constant["b"] * math.sin(theta)
    return result


def predict_hours(model, start_hour, count):
    return [predict_height(model, start_hour + i) for i in range(count + 1)]


def find_extrema(model, start_hour, hours, grid_minutes, minimum_range):
    count = hours * 60 // grid_minutes
    minutes = [
        start_hour * 60 + i * grid_minutes for i in range(count + 1)
    ]
    heights = [predict_height(model, minute / 60) for minute in minutes]
    extrema = []
    for j in range(1, count):
        left, center, right = heights[j - 1:j + 2]
        if left < center > right:
            kind = "high"
        elif left > center < right:
            kind = "low"
        else:
            continue
        delta = (left - right) / (2 * (left - 2 * center + right))
        precise_minute = minutes[j] + delta * grid_minutes
        height = center - (left - right) * delta / 4
        extrema.append({
            "kind": kind, "minute": precise_minute,
            "rounded": math.floor(precise_minute + 0.5),
            "height": height,
        })
    raw = len(extrema)
    while len(extrema) >= 2:
        index = min(range(len(extrema) - 1),
                    key=lambda i: abs(extrema[i]["height"] - extrema[i + 1]["height"]))
        if abs(extrema[index]["height"] - extrema[index + 1]["height"]) >= minimum_range:
            break
        del extrema[index:index + 2]
    return extrema, raw


def label_extrema(extrema, epoch):
    by_date = {}
    for item in extrema:
        date = date_at_minute(epoch, item["rounded"])
        item["date"] = date
        by_date.setdefault(date, []).append(item)
    for group in by_date.values():
        highs = [item for item in group if item["kind"] == "high"]
        lows = [item for item in group if item["kind"] == "low"]
        if highs:
            best = max(highs, key=lambda item: item["height"])
            for item in highs:
                item["label"] = "HHW" if item is best else "LHW"
        if lows:
            best = min(lows, key=lambda item: item["height"])
            for item in lows:
                item["label"] = "LLW" if item is best else "HLW"
    return extrema

import csv
from datetime import datetime, timedelta
from pathlib import Path


DATE_FORMAT = "%Y-%m-%d %H:%M"


def parse_datetime(text):
    return datetime.strptime(text, DATE_FORMAT)


def parse_settings(path="input/params.txt"):
    lines = Path(path).read_text(encoding="ascii").splitlines()
    epoch = parse_datetime(lines[0][len("epoch "):])
    stations = []
    cursor = 1
    while lines[cursor].startswith("station "):
        _, code, name = lines[cursor].split(" ", 2)
        stations.append({"code": code, "name": name})
        cursor += 1
    values = {}
    for line in lines[cursor:]:
        keyword, argument = line.split(" ", 1)
        values[keyword] = argument
    spike = values["spike"].split()
    surge = values["surge"].split()
    prediction = values["predict"].split()
    plot = values["plot"].split()
    return {
        "epoch": epoch,
        "stations": stations,
        "reference": values["reference"],
        "flat_run": int(values["flat_run"]),
        "spike_window": int(spike[0]),
        "spike_minimum": int(spike[1]),
        "spike_factor": float(spike[2]),
        "spike_floor": float(spike[3]),
        "rayleigh": float(values["rayleigh"]),
        "snr_min": float(values["snr_min"]),
        "top_residuals": int(values["top_residuals"]),
        "surge_threshold": float(surge[0]),
        "surge_hours": int(surge[1]),
        "prediction_start": parse_datetime(" ".join(prediction[:2])),
        "prediction_hours": int(prediction[2]),
        "grid_minutes": int(values["grid_minutes"]),
        "min_range": float(values["min_range"]),
        "correlation_lag": int(values["correlation_lag"]),
        "plot_code": plot[0],
        "plot_hours": int(plot[1]),
        "plot_top": int(plot[2]),
        "plot_bottom": int(plot[3]),
        "plot_step": int(plot[4]),
    }


def epoch_hours(epoch, instant):
    delta = instant - epoch
    return delta.days * 24 + delta.seconds // 3600


def epoch_minutes(epoch, instant):
    delta = instant - epoch
    return delta.days * 1440 + delta.seconds // 60


def datetime_at_hour(epoch, hour):
    return (epoch + timedelta(hours=hour)).strftime(DATE_FORMAT)


def datetime_at_minute(epoch, minute):
    return (epoch + timedelta(minutes=minute)).strftime(DATE_FORMAT)


def date_at_hour(epoch, hour):
    return (epoch + timedelta(hours=hour)).date()


def date_at_minute(epoch, minute):
    return (epoch + timedelta(minutes=minute)).date()


def noon_hour(epoch, date):
    noon = datetime(date.year, date.month, date.day, 12, 0)
    return epoch_hours(epoch, noon)


def read_constituents(path="input/constituents.txt"):
    lines = Path(path).read_text(encoding="ascii").splitlines()
    count = int(lines[0])
    if count != len(lines) - 1:
        raise ValueError("constituent count mismatch")
    result = []
    for line in lines[1:]:
        name, speed = line.split(" ")
        result.append({"name": name, "speed": float(speed)})
    return result


def read_observations(epoch, stations, path="input/observations.csv"):
    table = {station["code"]: {"values": {}, "rows": 0} for station in stations}
    with open(path, encoding="ascii", newline="") as handle:
        for row in list(csv.reader(handle))[1:]:
            code, time_text, value_text = row
            hour = epoch_hours(epoch, parse_datetime(time_text))
            table[code]["values"][hour] = None if value_text == "NA" else float(value_text)
            table[code]["rows"] += 1
    return table


def read_all_inputs():
    settings = parse_settings()
    constituents = read_constituents()
    observations = read_observations(settings["epoch"], settings["stations"])
    return settings, constituents, observations

import math
from pathlib import Path

from predict import predict_height


def decimal(value, places):
    result = f"{value:.{places}f}"
    if result.startswith("-") and float(result) == 0.0:
        return result[1:]
    return result


def optional(value, places):
    return "none" if value is None else decimal(value, places)


def write_lines(name, lines):
    target = Path("output") / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("\n".join(lines) + "\n", encoding="ascii")


def render_plot(model, extrema, start_hour, width, top, bottom, step):
    rows = (top - bottom) // step + 1
    grid = [[" " for _ in range(width)] for _ in range(rows)]
    zero_row = math.floor((top - 100 * model["mean_level"]) / step + 0.5)
    if 0 <= zero_row < rows:
        for column in range(width):
            grid[zero_row][column] = "-"
    marks = {}
    for item in extrema:
        column = (item["rounded"] - 60 * start_hour + 30) // 60
        if 0 <= column < width:
            marks[column] = "H" if item["kind"] == "high" else "L"
    for column in range(width):
        level = predict_height(model, start_hour + column)
        row = math.floor((top - 100 * level) / step + 0.5)
        if row < 0:
            grid[0][column] = "^"
        elif row >= rows:
            grid[-1][column] = "v"
        else:
            grid[row][column] = marks.get(column, "*")
    labels = [decimal((top - row * step) / 100, 2) for row in range(rows)]
    label_width = max(map(len, labels))
    lines = [
        f"{label:>{label_width}} |{''.join(cells)}|"
        for label, cells in zip(labels, grid)
    ]
    axis = "".join("+" if column % 6 == 0 else "-" for column in range(width))
    lines.append(" " * label_width + " +" + axis + "+")
    return lines
